    assert.strictEqual(marked.parse('[foo [bar](/uri)](/uri)'), '<p>[foo <a href="/uri">bar</a>](/uri)</p>\n');
  });

  it('should not nest a link in a reference link', () => {
    assert.strictEqual(marked.parse('[foo [bar](/uri)][ref]\n\n[ref]: /uri'), '<p>[foo <a href="/uri">bar</a>]<a href="/uri">ref</a></p>\n');
  });

  it('should not nest links at any depth', () => {
    assert.strictEqual(marked.parse('[foo *[bar [baz](/uri)](/uri)*](/uri)'), '<p>[foo <em>[bar <a href="/uri">baz</a>](/uri)</em>](/uri)</p>\n');
  });

  it('should still allow images in links', () => {
